@RestController
@RequestMapping("/api/v1/customers")
public class CustomerController {

  @PostMapping
  @PreAuthorize("hasAnyRole('CUSTOMER_SERVICE_AGENT', 'ADMIN')")
  public ResponseEntity<ApiResponse<CustomerResponse>> createCustomer(
    @Valid @RequestBody CreateCustomerRequest request
  ) {
    CustomerResponse response = customerService.createCustomer(request);
    return ResponseEntity.status(HttpStatus.CREATED).body(
      new ApiResponse<>(response, metadata)
    );
  }
}

@Service
public class CustomerService {

  public CustomerResponse createCustomer(CreateCustomerRequest request) {
    // Check email uniqueness
    if (customerRepository.findByEmail(request.getEmail()).isPresent()) {
      throw new CustomerAlreadyExistsException("Customer with this email already exists");
    }

    // Map to entity
    Customer customer = new Customer();
    customer.setFirstName(request.getFirstName());
    customer.setLastName(request.getLastName());
    customer.setEmail(request.getEmail());
    customer.setStatus(Status.ACTIVE); // Default
    // ... set other fields

    // Save
    Customer saved = customerRepository.save(customer);

    // Audit
    auditService.createAuditEntry(Operation.CREATE, "CUSTOMER", saved.getCustomerId(), user);

    // Return response
    return CustomerResponse.from(saved);
  }
}

public class CreateCustomerRequest {
  @NotNull @Size(min=1, max=100)
  private String firstName;

  @NotNull @Size(min=1, max=100)
  private String lastName;

  private LocalDate dateOfBirth;

  @NotNull @Email
  private String email;

  @Pattern(regexp = "^\\+?[1-9]\\d{1,14}$")
  private String phone;

  private String address;
  private String city;
  private String state;
  private String zipCode;

  // Getters and setters
}

public class CustomerResponse {
  private UUID customerId;
  private String firstName;
  private String lastName;
  private String email;
  private String phone;
  private Status status;
  private LocalDateTime createdAt;
  private LocalDateTime updatedAt;

  public static CustomerResponse from(Customer customer) {
    // Map entity to DTO
  }

  // Getters and setters
}

public class ApiResponse<T> {
  private T data;
  private Map<String, Object> metadata;

  public ApiResponse(T data, Map<String, Object> metadata) {
    this.data = data;
    this.metadata = metadata;
    this.metadata.put("timestamp", LocalDateTime.now());
    this.metadata.put("version", "v1");
  }

  // Getters and setters
}

@Service
public class AuditService {
  public void createAuditEntry(
    Operation operation,
    String entityType,
    UUID entityId,
    String user
  ) {
    AuditLog auditLog = new AuditLog();
    auditLog.setOperation(operation);
    auditLog.setEntityType(entityType);
    auditLog.setEntityId(entityId);
    auditLog.setUserId(user);
    auditLog.setTimestamp(LocalDateTime.now());
    auditLogRepository.save(auditLog);
  }
}

public interface CustomerRepository extends JpaRepository<Customer, UUID> {
  Optional<Customer> findByEmail(String email);
}
